import { useEffect, useState } from "react";
import { doc, onSnapshot } from "firebase/firestore";
import { db } from "../firebase";

// 고객확인서의 작업자 명판(업체명·전화번호·사업자등록번호·도장)은 일정을 저장하는 시점에
// 스냅샷으로 함께 저장해둔다(schedules.assigneeDetails → confirmations.workers). 그런데
// 담당자가 그 이후에 설정 화면에서 사업자등록번호를 새로 입력하거나 도장(서명) 이미지를
// 새로 올리면, 이미 저장돼 있던 옛 스냅샷에는 반영되지 않아 "분명히 등록했는데 안 보인다"는
// 문제가 생긴다. 이 훅은 uid가 있는 작업자에 한해 workerDirectory의 "지금 이 순간" 값으로
// 업체명/전화번호/사업자등록번호/도장/이름을 덮어써서, 언제 보든(방금 서명받을 때든, 나중에
// 다시 열어볼 때든) 항상 최신 정보가 보이도록 한다. uid가 없거나(옛 방식으로 저장된 문서)
// 그 사이 계정이 삭제되는 등 workerDirectory 문서 자체가 없으면 저장된 스냅샷 값을 그대로 쓴다.
export default function useWorkerDirectoryOverrides(workers) {
  const uids = Array.from(new Set((workers || []).map((w) => w.uid).filter(Boolean)));
  const uidsKey = uids.join(",");
  const [live, setLive] = useState({});

  useEffect(() => {
    if (uids.length === 0) { setLive({}); return; }
    const unsubs = uids.map((uid) =>
      onSnapshot(doc(db, "workerDirectory", uid), (snap) => {
        setLive((prev) => ({ ...prev, [uid]: snap.exists() ? snap.data() : null }));
      })
    );
    return () => unsubs.forEach((u) => u());
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [uidsKey]);

  return (workers || []).map((w) => {
    const liveDoc = w.uid ? live[w.uid] : null;
    if (!liveDoc) return w;
    return {
      ...w,
      name: liveDoc.name || w.name,
      companyName: liveDoc.companyName || w.companyName,
      phone: liveDoc.phone || w.phone,
      businessNumber: liveDoc.businessNumber || w.businessNumber,
      signatureUrl: liveDoc.signatureUrl || w.signatureUrl,
    };
  });
}
