import { S } from "../styles/theme";

// ── 시간 입력(시/분 드롭다운) ─────────────────────────────────────
// 브라우저 기본 <input type="time">은 기기의 네이티브 시간 선택창(아날로그 시계 다이얼 등)을
// 그대로 띄우는데, 일부 안드로이드 기기(화면 크기·글자 크기 설정에 따라)에서는 그 다이얼
// 안의 "설정"(확인) 버튼이 화면 아래로 잘려서 아예 보이지 않아 시간을 입력할 수 없는 문제가
// 있었다. 기기·브라우저의 네이티브 UI에 의존하는 한 이 문제를 앱에서 직접 고칠 방법이 없어서,
// 아예 네이티브 시간 선택창을 쓰지 않는 시/분 드롭다운(<select>) 두 개로 대체했다 — 어떤
// 기기에서도 항상 똑같이, 잘리지 않고 보인다.
// 값은 기존과 동일하게 "HH:MM"(24시간, zero-padded) 문자열로 주고받아서, 이미 저장된
// 일정/고객확인서 데이터나 정렬 로직("HH:MM" 문자열 비교)에 영향이 없다.
const HOURS = Array.from({ length: 24 }, (_, i) => String(i).padStart(2, "0"));
const MINUTES = Array.from({ length: 12 }, (_, i) => String(i * 5).padStart(2, "0"));

export default function TimeSelect({ value, onChange }) {
  const [h, m] = (value || "").split(":");
  const hour = HOURS.includes(h) ? h : "";
  const minute = MINUTES.includes(m) ? m : "";

  const commit = (newHour, newMinute) => {
    if (!newHour && !newMinute) { onChange(""); return; }
    onChange(`${newHour || "00"}:${newMinute || "00"}`);
  };

  return (
    <div style={{ display: "flex", gap: 6 }}>
      <select
        style={{ ...S.input, flex: 1 }}
        value={hour}
        onChange={(e) => commit(e.target.value, minute)}
        aria-label="시"
      >
        <option value="">시</option>
        {HOURS.map((hh) => (
          <option key={hh} value={hh}>{hh}시</option>
        ))}
      </select>
      <select
        style={{ ...S.input, flex: 1 }}
        value={minute}
        onChange={(e) => commit(hour, e.target.value)}
        aria-label="분"
      >
        <option value="">분</option>
        {MINUTES.map((mm) => (
          <option key={mm} value={mm}>{mm}분</option>
        ))}
      </select>
    </div>
  );
}
