// ── 서명판 (고객이 화면에 직접 손가락/마우스로 서명) ──────────────
// 캔버스 렌더링(2d 컨텍스트)이 없는 환경(예: 테스트용 jsdom)에서도 입력 처리 자체는
// 그대로 동작하도록, ctx가 null이면 그리기만 건너뛰고 "서명함" 상태는 정상적으로 갱신한다.
const SignaturePad = forwardRef(function SignaturePad({ onChange, height = 160 }, ref) {
  const canvasRef = useRef();
  const drawingRef = useRef(false);
  const hasDrawnRef = useRef(false);
  const lastPointRef = useRef(null);

  const setupCanvas = () => {
    const canvas = canvasRef.current;
    if (!canvas) return;
    const rect = canvas.getBoundingClientRect();
    const ratio = window.devicePixelRatio || 1;
    const w = Math.max(rect.width, 1);
    const h = Math.max(rect.height, 1);
    canvas.width = w * ratio;
    canvas.height = h * ratio;
    const ctx = canvas.getContext("2d");
    if (!ctx) return;
    ctx.setTransform(1, 0, 0, 1, 0, 0);
    ctx.scale(ratio, ratio);
    ctx.fillStyle = "#ffffff";
    ctx.fillRect(0, 0, w, h);
    ctx.strokeStyle = "#1f2937";
    ctx.lineWidth = 2.5;
    ctx.lineCap = "round";
    ctx.lineJoin = "round";
  };

  useEffect(() => { setupCanvas(); }, []);

  useImperativeHandle(ref, () => ({
    isEmpty: () => !hasDrawnRef.current,
    clear: () => { setupCanvas(); hasDrawnRef.current = false; onChange?.(false); },
    getDataUrl: () => canvasRef.current.toDataURL("image/png"),
  }));

  const pointFromEvent = (e) => {
    const rect = canvasRef.current.getBoundingClientRect();
    return { x: e.clientX - rect.left, y: e.clientY - rect.top };
  };

  const handleDown = (e) => {
    e.preventDefault();
    canvasRef.current.setPointerCapture?.(e.pointerId);
    drawingRef.current = true;
    lastPointRef.current = pointFromEvent(e);
  };
  const handleMove = (e) => {
    if (!drawingRef.current) return;
    e.preventDefault();
    const p = pointFromEvent(e);
    const ctx = canvasRef.current.getContext("2d");
    if (ctx) {
      ctx.beginPath();
      ctx.moveTo(lastPointRef.current.x, lastPointRef.current.y);
      ctx.lineTo(p.x, p.y);
      ctx.stroke();
    }
    lastPointRef.current = p;
    if (!hasDrawnRef.current) { hasDrawnRef.current = true; onChange?.(true); }
  };
  const handleUp = () => { drawingRef.current = false; };

  return (
    <div>
      <canvas
        ref={canvasRef}
        style={{ width:"100%", height, touchAction:"none", display:"block", cursor:"crosshair",
          background:"#fff", borderRadius:10, border:`1px solid ${C.border2}` }}
        onPointerDown={handleDown}
        onPointerMove={handleMove}
        onPointerUp={handleUp}
        onPointerLeave={handleUp}
        onPointerCancel={handleUp}
      />
      <button type="button" onClick={()=>ref.current?.clear()}
        style={{ ...S.btnSecondary, marginTop:8, padding:"8px 12px", fontSize:12 }}>
        🔄 다시 서명
      </button>
    </div>
  );
});

// 저장된 확인서(c)에서 작업자 명판 목록을 뽑아낸다. 신규 문서는 c.workers(배열)를 그대로 쓰고,
// 이전 방식(workerName/workerCompany/workerPhone 단일 필드)으로 저장된 옛 문서도 계속 표시되도록
// 대체 경로를 둔다.
function getWorkerPlates(c) {
  if (Array.isArray(c.workers) && c.workers.length > 0) return c.workers;
  if (c.workerName) {
    return [{ name: c.workerName, companyName: c.workerCompany || "", phone: c.workerPhone || "",
      businessNumber: c.workerBusinessNumber || "", signatureUrl: c.workerSignatureUrl || "" }];
  }
  return [];
}

