//    그 아래 사업자등록번호·연락처를 작게 표시) ─────────────────────
function WorkerPlate({ w, dark }) {
  const boxBg = dark ? "rgba(255,255,255,0.08)" : "#f8fafc";
  const boxBorder = dark ? "1px solid rgba(255,255,255,0.18)" : "1px solid #e5e7eb";
  const nameColor = dark ? "#fff" : "#1f2937";
  const subColor = dark ? "#cbd5e1" : "#6b7280";
  return (
    <div style={{ background:boxBg, border:boxBorder, borderRadius:10,
      padding: dark ? "12px 14px" : "8px 10px", width:"100%", boxSizing:"border-box" }}>
      <div style={{ display:"flex", justifyContent:"space-between", alignItems:"center", gap:8 }}>
        <span style={{ fontSize: dark ? 16 : 13, fontWeight:800, color:nameColor }}>
          {w.companyName ? `${w.companyName} (대표 ${w.name})` : w.name}
        </span>
        {w.signatureUrl && (
          <img src={w.signatureUrl} alt="도장" crossOrigin="anonymous"
            style={{ height: dark ? 34 : 26, width:"auto", maxWidth:60, objectFit:"contain" }} />
        )}
      </div>
      {(w.businessNumber || w.phone) && (
        <div style={{ fontSize: dark ? 12.5 : 10.5, color:subColor, marginTop:6, lineHeight:1.6 }}>
          {w.businessNumber && <div>사업자등록번호: {w.businessNumber}</div>}
          {w.phone && <div>연락처: {fmt.phone(w.phone)}</div>}
        </div>
      )}
    </div>
  );
}

